{
  "case_id": "C10",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "What was tested",
      "narration": "An experimental drug called CardioRestore-7 was tested in 1,204 adults with stable heart failure. Half got the drug, half got a placebo, and for 52 weeks neither the patients nor their doctors knew which was which.",
      "on_screen": "Title card: CardioRestore-7 vs placebo. 1,204 adults, 602 per arm, 52 weeks, double-blind.",
      "claim_refs": ["Abstract: 1,204 adults, randomised 1:1", "Methods: double-blind, placebo-controlled, 52 weeks"]
    },
    {
      "beat": "The main result: no difference",
      "narration": "The question the researchers committed to in advance was whether the drug would reduce heart-related deaths or hospital stays for heart failure. It did not. There were 187 such events on the drug and 193 on placebo, a difference well within chance.",
      "on_screen": "Primary endpoint: 187/602 drug vs 193/602 placebo. HR 0.96, 95% CI 0.79-1.17, p = 0.68. Stamp: NULL RESULT.",
      "claim_refs": ["Results: Primary composite at 52 weeks, HR 0.96 (0.79-1.17), p = 0.68 - null"]
    },
    {
      "beat": "The walking test, in context",
      "narration": "One secondary measure did move. People on the drug walked about 14 metres further in a six-minute test. But researchers generally treat a change as meaningful for patients only above 30 metres, and this result was not statistically adjusted for testing several outcomes at once.",
      "on_screen": "Six-minute walk: +14 m (95% CI 3 to 25). Dashed line marked 'meaningful for patients: above ~30 m'. Note: secondary endpoint, not adjusted for multiplicity.",
      "claim_refs": ["Results: Six-minute walk distance (secondary), +14 m (95% CI 3 to 25)", "Background: minimum clinically important difference generally placed above 30 metres", "Methods: pre-specified secondary endpoint, not adjusted for multiplicity"]
    },
    {
      "beat": "A safety signal",
      "narration": "There was also a downside. Forty-seven people on the drug needed their dose reduced because of low blood pressure, compared with twelve on placebo.",
      "on_screen": "Hypotension requiring dose reduction: 47/602 drug vs 12/602 placebo.",
      "claim_refs": ["Results: Hypotension requiring dose reduction, 47/602 vs 12/602", "Methods: hypotension defined as systolic BP below 90 mmHg with symptoms or requiring dose reduction"]
    },
    {
      "beat": "Bottom line",
      "narration": "So: one trial, one year, and the main goal was missed. CardioRestore-7 is still investigational and is not approved by any regulator. It is not a treatment you can or should ask for yet.",
      "on_screen": "Investigational. Not approved by any regulator. Single trial, 52 weeks of follow-up.",
      "claim_refs": ["Results: Regulatory status, investigational; not approved", "Abstract: CardioRestore-7 is investigational and is not approved by any regulator", "Limitations: single trial; 52 weeks of follow-up"]
    }
  ]
}
